# Clasificador de las modalidades de estafa que recoge el tema.
# Simplificación: el Código Penal tiene más matices y excepciones.
# «transferencia ajena» = transferencia no consentida, con lucro.
PIEZAS = ["ánimo de lucro", "engaño bastante", "error",
          "acto de disposición", "perjuicio"]

def modalidad(h):
    if h.get("clona la tarjeta"):
        return "no es estafa: falsificación de tarjetas"
    if h.get("vende programas para estafar"):
        return "programas para estafar"
    if h.get("usa tarjeta ajena o sus datos"):
        return "uso fraudulento de tarjetas (estafa)"
    if h.get("manipula un sistema") and h.get("transferencia ajena"):
        return "estafa informática (sin engañar a nadie)"
    faltan = [p for p in PIEZAS if not h.get(p)]
    if faltan:
        return "no hay estafa: falta " + ", ".join(faltan)
    return "estafa clásica (Internet solo facilita)"

clasica = dict.fromkeys(PIEZAS, True)
casos = {
    "Móvil pagado que nunca llega": clasica,
    "Con claves robadas, se transfiere el saldo":
        {"manipula un sistema": True, "transferencia ajena": True},
    "Compra online con el número de tarjeta de otro":
        {"usa tarjeta ajena o sus datos": True},
    "Broma: anuncio falso sin cobrar nada":
        {"engaño bastante": True, "error": True},
}
for caso, hechos in casos.items():
    print(f"{caso}\n  -> {modalidad(hechos)}")
